7257: # Makes a record final (D3): state done, the exit code, finished and wall_seconds (from `started`)
7258: # unless already set, the summary ($Summary when given, else the one it has, else $Line, else a
7259: # pointer to the log), and every member still pending -> skipped "not started: <the first summary
7260: # line>", still running -> failed "stopped: the run ended (exit <e>) before this member finished".
7261: # Idempotent: the run's own final write and the background's confirmation after it agree.
7262: function Complete-DetachedRecord {
7263:     param($Record, [int]$Exit, [string]$Summary = '', [string]$Line = '')
7264:     $now = Get-Date
7265:     $Record.state = 'done'
7266:     $Record.exit = $Exit
7267:     if (-not $Record.finished) { $Record.finished = Get-IsoTimestamp $now }
7268:     if ($null -eq $Record.wall_seconds) {
7269:         $st = ConvertTo-WhenOffset $Record.started
7270:         if ($st) { $Record.wall_seconds = [math]::Round(([DateTimeOffset]$now - $st).TotalSeconds, 1) }
7271:     }
7272:     if ($Summary) { $Record.summary = $Summary }
7273:     elseif (-not $Record.summary) {
7274:         $Record.summary = $(if ($Line) { $Line } else { "codex-consult: the detached run ended with exit $Exit without a summary; its console output is in $($Record.log)" })
7275:     }
7276:     $why = ConvertTo-OneLine ((([string]$Record.summary) -split "`n")[0] -replace '^codex-consult:\s*', '')
7277:     if ($why.Length -gt 200) { $why = $why.Substring(0, 197) + '...' }
7278:     foreach ($m in @($Record.members | Where-Object { $_ })) {
7279:         if ($m.state -eq 'pending') { $m.state = 'skipped'; $m.outcome = "not started: $why" }
7280:         elseif ($m.state -eq 'running') { $m.state = 'failed'; $m.outcome = "stopped: the run ended (exit $Exit) before this member finished" }
7281:     }
